<script setup lang="ts">
import { computed, ref, watch } from 'vue';
import { DialogRoot, DialogPortal, DialogOverlay, DialogContent, DialogTitle, DialogDescription, DialogClose } from 'reka-ui';
import { X } from 'lucide-vue-next';
import type { AppSettings, GitRef, HistoryScope } from '../shared/protocol';
import { useLocale } from '../lib/vue-locale';
import { normalizeHistoryScope } from '../lib/settings-schema';
const props=defineProps<{open:boolean;refs:readonly GitRef[];settings:AppSettings;query:{scope:HistoryScope;search:string;searchMode:string;queryMode:'filter'|'search';order:string;filter?:{author?:string;hash?:string;refs?:string;after?:string;before?:string}}}>();
const emit=defineEmits<{'update:open':[open:boolean];apply:[query:{scope:HistoryScope;search:string;searchMode:'all'|'message'|'author'|'hash'|'date'|'refs';queryMode:'filter'|'search';filter:{author?:string;hash?:string;refs?:string;after?:string;before?:string}}]}>();
const {text}=useLocale();const scopeKind=ref<'all'|'head'|'refs'|'glob'|'group'>('all'),selected=ref<string[]>([]),include=ref(''),exclude=ref(''),group=ref(''),search=ref(''),mode=ref<'filter'|'search'>('filter'),field=ref<'all'|'message'|'author'|'hash'|'date'|'refs'>('all'),author=ref(''),hash=ref(''),refFilter=ref(''),after=ref(''),before=ref(''),error=ref('');
const groups=computed(()=>props.settings.branchGroups);
watch(()=>props.open,open=>{if(!open)return;scopeKind.value=props.query.scope.kind;selected.value=[...(props.query.scope.refs??[])];include.value=props.query.scope.include?.join('\n')??'';exclude.value=props.query.scope.exclude?.join('\n')??'';search.value=props.query.search;mode.value=props.query.queryMode;field.value=props.query.searchMode as typeof field.value;author.value=props.query.filter?.author??'';hash.value=props.query.filter?.hash??'';refFilter.value=props.query.filter?.refs??'';after.value=props.query.filter?.after??'';before.value=props.query.filter?.before??'';error.value='';});
function apply(){let scope:HistoryScope;if(scopeKind.value==='group'){const found=groups.value.find(item=>item.name===group.value);if(!found){error.value=text('请选择有效的命名组。','Select a valid named group.');return;}scope={kind:'glob',include:[...found.include],exclude:[...found.exclude]};}else scope={kind:scopeKind.value,...(scopeKind.value==='refs'?{refs:[...selected.value]}:scopeKind.value==='glob'?{include:include.value.split(/\n|,/).map(s=>s.trim()).filter(Boolean),exclude:exclude.value.split(/\n|,/).map(s=>s.trim()).filter(Boolean)}:{})};const normalized=normalizeHistoryScope(scope);if(!normalized){error.value=text('范围格式无效；请使用明确引用或有效的 glob。','Invalid scope. Use explicit references or valid globs.');return;}if(after.value&&before.value&&after.value>before.value){error.value=text('起始日期不能晚于结束日期。','Start date must not be after the end date.');return;}emit('apply',{scope:normalized,search:search.value,searchMode:field.value,queryMode:mode.value,filter:{author:author.value||undefined,hash:hash.value||undefined,refs:refFilter.value||undefined,after:after.value||undefined,before:before.value||undefined}});emit('update:open',false);}
</script>
<template><DialogRoot :open="open" @update:open="value=>emit('update:open',value)"><DialogPortal><DialogOverlay class="native-dialog-overlay"/><DialogContent class="native-dialog"><header class="query-header"><DialogTitle>{{ text('历史范围与查询','History scope and query') }}</DialogTitle><DialogClose class="wb-icon" :aria-label="text('关闭','Close')"><X :size="16"/></DialogClose></header><DialogDescription>{{ text('范围决定真实历史读取；已加载过滤与全历史搜索明确区分。高级字段过滤作用于已加载的查询结果。','Scope controls native history reads. Loaded filtering and full-history search are distinct. Advanced field filters apply to the loaded query results.') }}</DialogDescription><form class="query-form" @submit.prevent="apply"><label>{{ text('范围','Scope') }}<select v-model="scopeKind"><option value="all">{{ text('全部分支','All branches') }}</option><option value="head">HEAD</option><option value="refs">{{ text('多个明确引用','Explicit references') }}</option><option value="glob">{{ text('包含／排除 glob','Include / exclude globs') }}</option><option v-if="groups.length" value="group">{{ text('命名组','Named group') }}</option></select></label><fieldset v-if="scopeKind==='refs'"><legend>{{ text('选择引用（不检出）','Select references (no checkout)') }}</legend><label v-for="item in refs.filter(item=>item.kind!=='stash')" :key="item.fullName" class="ref-check"><input v-model="selected" type="checkbox" :value="item.fullName"/><span>{{ item.name }}</span></label></fieldset><template v-if="scopeKind==='glob'"><label>{{ text('包含，每行一个','Include, one per line') }}<textarea v-model="include" rows="2" placeholder="refs/heads/*"/></label><label>{{ text('排除，每行一个','Exclude, one per line') }}<textarea v-model="exclude" rows="2"/></label></template><label v-if="scopeKind==='group'">{{ text('命名组','Named group') }}<select v-model="group"><option disabled value="">{{ text('请选择','Choose a group') }}</option><option v-for="item in groups" :key="item.name">{{ item.name }}</option></select></label><div class="query-row"><label>{{ text('查询模式','Query mode') }}<select v-model="mode"><option value="filter">{{ text('仅过滤已加载提交','Filter loaded commits') }}</option><option value="search">{{ text('搜索全部历史','Search full history') }}</option></select></label><label>{{ text('字段','Field') }}<select v-model="field"><option value="all">{{ text('全部','All') }}</option><option value="message">{{ text('说明','Message') }}</option><option value="author">{{ text('作者','Author') }}</option><option value="hash">OID</option><option value="date">{{ text('日期','Date') }}</option><option value="refs">{{ text('引用','References') }}</option></select></label></div><label>{{ text('搜索内容','Search') }}<input v-model="search" type="search"/></label><details><summary>{{ text('高级结果过滤','Advanced result filters') }}</summary><div class="query-form"><label>{{ text('作者／邮箱','Author / email') }}<input v-model="author"/></label><label>OID<input v-model="hash"/></label><label>{{ text('引用','References') }}<input v-model="refFilter"/></label><div class="query-row"><label>{{ text('从','From') }}<input v-model="after" type="date"/></label><label>{{ text('到（含当天）','Through (inclusive)') }}<input v-model="before" type="date"/></label></div></div></details><p v-if="error" class="error" role="alert">{{ error }}</p><footer><DialogClose class="wb-button">{{ text('取消','Cancel') }}</DialogClose><button type="submit" class="wb-button primary">{{ text('应用查询','Apply query') }}</button></footer></form></DialogContent></DialogPortal></DialogRoot></template>
<style scoped>.query-header{display:flex;align-items:center;justify-content:space-between;gap:10px}.query-form{display:flex;flex-direction:column;gap:12px}.query-row{display:flex;gap:10px}.query-row>label{flex:1;min-width:0}fieldset{border:1px solid var(--line);padding:8px;max-height:180px;overflow:auto}label.ref-check{display:flex;flex-direction:row;align-items:center;gap:8px;padding:4px}.ref-check input{width:auto}summary{font-size:12px;color:var(--muted);padding-bottom:8px}</style>
